// Persistent display snapshots. Never use these as transaction authorization.
import { CHAIN, CONTRACTS } from './chain-config.js';
import { registerReadCacheInvalidator } from './read-provider.js';
import { subscribe } from './store.js';

export const DISPLAY_REFRESH_MS = 6 * 60 * 60_000;
const RETRY_MS = 60_000;
const memory = new Map(), flights = new Map(), retries = new Map(), listeners = new Set();
let generation = 0;
const prefix = () => `degenerus:display:v1:${CHAIN.id}:${CONTRACTS.GAME}:${CONTRACTS.DEITY_PASS}:${CONTRACTS.AFKING_SUB_TOKEN}:`.toLowerCase();
const keyFor = key => prefix() + String(key).toLowerCase();
function encode(_key, value) {
  if (typeof value === 'bigint') return { $display: 'bigint', value: String(value) };
  if (value instanceof Map) return { $display: 'map', value: [...value] };
  if (value instanceof Set) return { $display: 'set', value: [...value] };
  return value;
}
function decode(_key, value) {
  if (value?.$display === 'bigint') return BigInt(value.value);
  if (value?.$display === 'map') return new Map(value.value);
  if (value?.$display === 'set') return new Set(value.value);
  return value;
}
function emit(key) { for (const listener of listeners) { try { listener(key); } catch (_) {} } }
export function subscribeDisplayCache(listener) { listeners.add(listener); return () => listeners.delete(listener); }

export function readDisplaySnapshot(key) {
  const id = keyFor(key);
  if (memory.has(id)) return memory.get(id);
  try {
    const entry = JSON.parse(localStorage.getItem(id), decode);
    if (!entry || entry.value == null || !Number.isSafeInteger(entry.savedAt)
      || entry.savedAt < 0 || entry.savedAt > Date.now()) return null;
    memory.set(id, entry);
    return entry;
  } catch (_) { return null; }
}

export function writeDisplaySnapshot(key, value, savedAt = Date.now()) {
  if (value == null) return;
  const id = keyFor(key), entry = { value, savedAt };
  memory.set(id, entry);
  while (memory.size > 128) memory.delete(memory.keys().next().value);
  try { localStorage.setItem(id, JSON.stringify(entry, encode)); } catch (_) { /* Memory still works. */ }
}

/** Expire saved data without blanking it, and reject pre-transaction writes. */
export function invalidateDisplaySnapshots(matches = () => true) {
  generation++;
  flights.clear(); retries.clear();
  const scope = prefix();
  const keys = new Set([...memory.keys()].filter(key => key.startsWith(scope)));
  try { for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i); if (key?.startsWith(scope)) keys.add(key);
  } } catch (_) {}
  for (const id of keys) {
    const key = id.slice(scope.length), entry = readDisplaySnapshot(key);
    if (entry && matches(key)) writeDisplaySnapshot(key, entry.value, 0);
  }
  emit(null);
}
registerReadCacheInvalidator(invalidateDisplaySnapshots);

// Draws can award tickets and debit subscriptions without this wallet sending
// a transaction. Refresh once on a new game day, not on each UI poll.
subscribe('app.daySync', state => {
  const day = Number(state?.day);
  if (!Number.isInteger(day) || day <= 0) return;
  const previous = readDisplaySnapshot('game-day')?.value;
  if (previous === day) return;
  writeDisplaySnapshot('game-day', day);
  if (previous != null) invalidateDisplaySnapshots(key => key.startsWith('ticket:') || key.startsWith('afking:'));
});

/** Saved values resolve immediately; one background refresh repairs stale data. */
export async function loadDisplaySnapshot(key, read, { fresh = false, maxAge = DISPLAY_REFRESH_MS } = {}) {
  const id = keyFor(key), saved = readDisplaySnapshot(key);
  const age = saved ? Date.now() - saved.savedAt : Infinity;
  if (!fresh && saved && saved.savedAt > 0 && age < maxAge) return saved.value;
  if (!fresh && (retries.get(id) ?? 0) > Date.now()) return saved?.value ?? null;
  if (!flights.has(id)) {
    const revision = generation;
    const flight = Promise.resolve().then(read).then(value => {
      if (value == null) throw new Error('Display snapshot unavailable');
      if (revision === generation) {
        const changed = JSON.stringify(saved?.value, encode) !== JSON.stringify(value, encode);
        writeDisplaySnapshot(key, value);
        retries.delete(id);
        if (changed) emit(key);
      }
      return value;
    }).catch(error => {
      if (revision === generation) retries.set(id, Date.now() + RETRY_MS);
      throw error;
    }).finally(() => { if (flights.get(id) === flight) flights.delete(id); });
    flights.set(id, flight);
  }
  const flight = flights.get(id);
  if (saved && !fresh) { void flight.catch(() => {}); return saved.value; }
  return flight;
}

/** Test seam: emulate a new page without clearing persistent storage. */
export function resetDisplayCacheMemoryForTest() {
  generation++; memory.clear(); flights.clear(); retries.clear();
}
